using System.Linq;
using System.Collections.Generic;
using Autodesk.Revit.DB;

var doc = Document;
// setup: a floor plan with no view template (so its filters are editable)
var view = new FilteredElementCollector(doc).OfClass(typeof(ViewPlan)).Cast<ViewPlan>()
    .First(v => !v.IsTemplate && v.ViewType == ViewType.FloorPlan && v.ViewTemplateId == ElementId.InvalidElementId);
var cats = new List<ElementId> { new ElementId(BuiltInCategory.OST_Walls) };
var commentsParam = new ElementId(BuiltInParameter.ALL_MODEL_INSTANCE_COMMENTS);

ElementId filterId = null;
int flaggedWalls = 0;
// step 1: create a flagged wall, a rule-based filter matching it, and a red override
Connector.WithTransaction(doc, () => {
    var level = new FilteredElementCollector(doc).OfClass(typeof(Level)).Cast<Level>().OrderBy(l => l.Elevation).First();
    var wallType = new FilteredElementCollector(doc).OfClass(typeof(WallType)).Cast<WallType>().First(wt => wt.Kind == WallKind.Basic);
    var w = Wall.Create(doc, Line.CreateBound(new XYZ(0, 40, 0), new XYZ(20, 40, 0)), wallType.Id, level.Id, 10, 0, false, false);
    w.get_Parameter(BuiltInParameter.ALL_MODEL_INSTANCE_COMMENTS).Set("QA-FLAG");

    var rule = ParameterFilterRuleFactory.CreateEqualsRule(commentsParam, "QA-FLAG");
    var ef = new ElementParameterFilter(rule);
    var pfe = ParameterFilterElement.Create(doc, "MCP QA Walls " + System.Guid.NewGuid().ToString("N").Substring(0, 4), cats, ef);
    filterId = pfe.Id;

    var ogs = new OverrideGraphicSettings();
    ogs.SetProjectionLineColor(new Color(255, 0, 0));
    ogs.SetSurfaceForegroundPatternColor(new Color(255, 0, 0));
    view.SetFilterOverrides(filterId, ogs);   // auto-adds the filter to the view

    flaggedWalls = new FilteredElementCollector(doc).OfCategory(BuiltInCategory.OST_Walls).WhereElementIsNotElementType()
        .Count(e => e.get_Parameter(BuiltInParameter.ALL_MODEL_INSTANCE_COMMENTS)?.AsString() == "QA-FLAG");
});

// verify: the filter is on the view and its override colour reads back
var filtersOnView = view.GetFilters().Select(id => doc.GetElement(id).Name).ToList();
var ov = view.GetFilterOverrides(filterId);
var c = ov.ProjectionLineColor;
return new {
    filterId = filterId.ToString(),
    viewName = view.Name,
    flaggedWalls,
    filtersOnView,
    projectionLineColor = c.IsValid ? $"{c.Red},{c.Green},{c.Blue}" : "invalid"
};
